-- v16 — session, identity, rate-limit, financial, and fraud hardening.
drop index if exists public.mdllni_profiles_email_uniq;
create or replace function public.mdllni_rate_bump(p_key text,p_now_ms bigint,p_window_ms bigint) returns jsonb language plpgsql security definer set search_path to '' as $$
declare r public.mdllni_rate_limits%rowtype;begin if p_key is null or length(p_key)<3 or p_window_ms<1000 then raise exception 'bad_rate_limit_input';end if;insert into public.mdllni_rate_limits as x(key,count,first,items,updated_at) values(p_key,1,p_now_ms,'[]'::jsonb,now()) on conflict(key) do update set count=case when p_now_ms-x.first>=p_window_ms then 1 else x.count+1 end,first=case when p_now_ms-x.first>=p_window_ms then p_now_ms else x.first end,updated_at=now() returning * into r;return jsonb_build_object('count',r.count,'first',r.first,'items',coalesce(r.items,'[]'::jsonb));end $$;
create or replace function public.mdllni_complete_order(p_order text,p_actor uuid) returns jsonb language plpgsql security definer set search_path to '' as $$
declare o public.mdllni_orders%rowtype;v_extra bigint:=0;v_price bigint;v_unit bigint:=250;v_rate numeric;v_raw numeric;v_commission bigint;v_delta integer;v_debt bigint;v_updated integer;begin select * into o from public.mdllni_orders where id=p_order for update;if not found then raise exception 'order_not_found';end if;if o.status<>'started' then raise exception 'order_unavailable';end if;if o.provider_id is null then raise exception 'provider_missing';end if;if o.provider_id<>p_actor and not exists(select 1 from public.mdllni_profiles where id=p_actor and role='admin' and status='active') then raise exception 'forbidden';end if;if o.disputed or exists(select 1 from public.mdllni_tickets where order_id=o.id and status='open') then raise exception 'disputed_open';end if;if o.final_price is not null and o.final_price<>o.estimate and not o.price_confirmed then raise exception 'price_not_confirmed';end if;if exists(select 1 from jsonb_array_elements(coalesce(o.extras,'[]'::jsonb))x where coalesce(x->>'status','') in('pending','proposed'))then raise exception 'extras_pending';end if;select coalesce(sum(case when coalesce(x->>'status','')='approved' or coalesce(x->>'approved','false')='true' then case when coalesce(x->>'amount',x->>'price','')~'^[0-9]+$' then coalesce(x->>'amount',x->>'price')::bigint else 0 end else 0 end),0) into v_extra from jsonb_array_elements(coalesce(o.extras,'[]'::jsonb))x;v_price:=coalesce(o.final_price,o.estimate)+v_extra;if v_price<=0 then raise exception 'invalid_price';end if;select coalesce(nullif(value->>'roundingUnit','')::bigint,250)into v_unit from public.mdllni_settings where key='debt';v_unit:=greatest(coalesce(v_unit,250),1);v_rate:=coalesce(o.commission_rate,15);if v_rate<0 or v_rate>100 then raise exception 'invalid_commission_rate';end if;v_raw:=v_price*v_rate/100;v_commission:=(round(v_raw/v_unit)*v_unit)::bigint;v_delta:=round(v_commission-v_raw)::integer;if exists(select 1 from public.mdllni_ledger where order_id=o.id and kind='commission')then raise exception 'already_completed';end if;v_debt:=public.mdllni_apply_debt(o.provider_id,v_commission,'commission',o.id,'عمولة الطلب المكتمل '||o.id);if v_debt is null then raise exception 'provider_missing';end if;update public.mdllni_providers set jobs=jobs+1,balance=balance+v_price where profile_id=o.provider_id;get diagnostics v_updated=row_count;if v_updated<>1 then raise exception 'provider_missing';end if;update public.mdllni_orders set status='done',done_at=now(),final_price=v_price,commission_amount=v_commission,rounding_delta=v_delta,timeline=coalesce(o.timeline,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('s','done','at',(extract(epoch from clock_timestamp())*1000)::bigint)) where id=o.id and status='started';get diagnostics v_updated=row_count;if v_updated<>1 then raise exception 'order_race';end if;insert into public.mdllni_audit_log(actor,action,created_at)values(coalesce((select name from public.mdllni_profiles where id=p_actor),'system'),'إكمال ذري للطلب '||o.id||' — عمولة '||v_commission,now());return jsonb_build_object('orderId',o.id,'price',v_price,'commission',v_commission,'roundingDelta',v_delta,'debt',v_debt);end $$;
create or replace function public.mdllni_confirm_settlement(p_payout text,p_actor uuid) returns jsonb language plpgsql security definer set search_path to '' as $$
declare po public.mdllni_payouts%rowtype;v_debt bigint;v_updated integer;begin if not exists(select 1 from public.mdllni_profiles where id=p_actor and role='admin' and status='active')then raise exception 'forbidden';end if;select * into po from public.mdllni_payouts where id=p_payout for update;if not found or po.status<>'pending' then raise exception 'payout_unavailable';end if;update public.mdllni_payouts set status='paid',paid_at=now()where id=po.id and status='pending';get diagnostics v_updated=row_count;if v_updated<>1 then raise exception 'payout_race';end if;v_debt:=public.mdllni_apply_debt(po.provider_id,-po.amount,'payment','', 'تأكيد استلام سداد '||po.id);if v_debt is null then raise exception 'provider_missing';end if;update public.mdllni_providers set settled=settled+po.amount where profile_id=po.provider_id;insert into public.mdllni_audit_log(actor,action,created_at)values((select name from public.mdllni_profiles where id=p_actor),'تأكيد سداد ذري '||po.id||' — '||po.amount,now());return jsonb_build_object('payoutId',po.id,'providerId',po.provider_id,'amount',po.amount,'debt',v_debt);end $$;
update public.mdllni_devices set status='revoked',revoked_at=now(),revoked_reason='trust_expired',note='انتهت مدة الثقة — يتطلب OTP جديد' where status='active' and(trusted_until is null or trusted_until<=now());
do $$begin if not exists(select 1 from pg_constraint where conname='mdllni_devices_active_trust_check')then alter table public.mdllni_devices add constraint mdllni_devices_active_trust_check check(status<>'active' or trusted_until is not null)not valid;end if;end $$;alter table public.mdllni_devices validate constraint mdllni_devices_active_trust_check;
revoke all on function public.mdllni_rate_bump(text,bigint,bigint)from public,anon,authenticated;revoke all on function public.mdllni_complete_order(text,uuid)from public,anon,authenticated;revoke all on function public.mdllni_confirm_settlement(text,uuid)from public,anon,authenticated;grant execute on function public.mdllni_rate_bump(text,bigint,bigint)to service_role;grant execute on function public.mdllni_complete_order(text,uuid)to service_role;grant execute on function public.mdllni_confirm_settlement(text,uuid)to service_role;
